```python
def solve():
    """Solves the painting problem."""

    # One person paints 1/2 house in 5 days.
    rate_per_person = (1/2) / 5  # House per day

    # 5 people working together
    combined_rate = 5 * rate_per_person

    # Time to paint a whole house
    time_to_paint = 1 / combined_rate  # Days

    # Convert days to hours
    time_to_paint_hours = time_to_paint * 24

    print(int(time_to_paint_hours))

solve()
```

